def transform(grid):
    h, w = len(grid), len(grid[0])
    # Recover the repeated horizontal pattern by majority vote per column,
    # excluding the displaced diagonal cells.
    col_values = []
    for c in range(w):
        vals = [grid[r][c] for r in range(h) if r != c and grid[r][c] != 0]
        col_values.append(Counter(vals).most_common(1)[0][0] if vals else None)
    # Extend any missing column from the cyclic color sequence inferred from
    # the other columns' horizontal progression.
    known = [(i, v) for i, v in enumerate(col_values) if v is not None]
    if not known:
        return [row[:] for row in grid]
    # The pattern follows the cycle of values in the source grid. Infer its
    # successor order from adjacent known columns, including wraparound.
    succ = {}
    for i in range(w - 1):
        a, b = col_values[i], col_values[i + 1]
        if a is not None and b is not None and a != b:
            succ[a] = b
    # Fill missing template positions from nearest known column using the
    # observed successor/predecessor relation.
    pred = {b: a for a, b in succ.items()}
    for i in range(w):
        if col_values[i] is None:
            left = next((j for j in range(i - 1, -1, -1) if col_values[j] is not None), None)
            right = next((j for j in range(i + 1, w) if col_values[j] is not None), None)
            if left is not None and col_values[left] in succ:
                v = col_values[left]
                for _ in range(i - left):
                    v = succ.get(v, v)
                col_values[i] = v
            elif right is not None and col_values[right] in pred:
                v = col_values[right]
                for _ in range(right - i):
                    v = pred.get(v, v)
                col_values[i] = v
            else:
                col_values[i] = col_values[left if left is not None else right]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                if r == c:
                    # The diagonal duplicates the preceding horizontal value.
                    out[r][c] = col_values[c - 1] if c > 0 else pred.get(col_values[0], col_values[0])
                else:
                    out[r][c] = col_values[c]
    return out
